from pathlib import Path
import json,hashlib,collections
task='DEV-PRED-PROD-DIFF-INVENTORY-20261005-E001'
source='8511127a874f323cc46cf701b2e9286d287f0b9a'
base=Path.home()/'.local/share/prediction-chat-bridge'
marker='PRODUCTION_COMPARE_WORKTREE '
found=[]
for folder in ('sent','inflight','outbox'):
    directory=base/folder
    if not directory.is_dir():
        continue
    for p in sorted(directory.glob('*.json'),key=lambda x:x.name,reverse=True)[:500]:
        if p.is_symlink() or not p.is_file() or p.stat().st_size>2000000:
            continue
        try:
            record=json.loads(p.read_text(encoding='utf-8'))
        except (ValueError,OSError):
            continue
        msg=str(record.get('message') or '')
        if ('PROJECT_TASK_ID='+task) not in msg and ('DEV_TASK_ID='+task) not in msg:
            continue
        for line in msg.splitlines():
            if line.startswith(marker):
                try:
                    payload=json.loads(line[len(marker):])
                except ValueError:
                    continue
                if payload.get('source_commit')==source:
                    found.append({'event_file':p.name,'message_sha256':hashlib.sha256(msg.encode()).hexdigest(),'payload':payload})
out=Path.cwd()/'diagnostic-result'
out.mkdir(exist_ok=True)
if not found:
    (out/'production-inventory-evidence.json').write_text(json.dumps({'status':'EVIDENCE_NOT_AVAILABLE','task_id':task,'production_modified':False},indent=2))
    print('PROD_DIFF EVIDENCE_NOT_AVAILABLE inventory_log_not_found; no comparison rerun',flush=True)
    raise SystemExit(2)
unique={json.dumps(x['payload'],sort_keys=True) for x in found}
if len(unique)!=1:
    print('PROD_DIFF CONFLICTING_INVENTORY_EVIDENCE',flush=True)
    raise SystemExit(3)
r=found[0]['payload']
diff=r.get('different',[])
missing=r.get('missing_in_source',[])
groups=dict(collections.Counter(str(Path(x).parent) for x in missing))
report={'task_id':task,'source_commit':source,'evidence':found,'missing_groups':groups,'production_modified':False,'test_rerun':False}
(out/'production-inventory-evidence.json').write_text(json.dumps(report,indent=2))
short=[Path(x).name.removesuffix('.py') for x in diff]
compact={'different':r.get('different_count'),'missing':r.get('missing_in_source_count'),'names':short}
print('PROD_DIFF '+json.dumps(compact,separators=(',',':')),flush=True)
raise SystemExit(0 if r.get('exact') is True else 1)
